{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "A close scaffold analogue sharing the same Cn1c(=O)n(...)c2...ncc21 core showed 67% oral bioavailability in human PK predictions, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Paltusotine, a heteroaromatic oral drug with a nitrile and similar lipophilic/aromatic character, had absolute oral bioavailability of 69% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Linagliptin, a related fused heterocyclic oral drug with a methylxanthine-like core, had absolute oral bioavailability of about 30%, still above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Rutaecarpine, a fused polycyclic alkaloid, showed low oral bioavailability, providing a contradictory low-F anchor, but its structural transfer to the query is weak.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tariquidar, a large heteroaromatic P-gp substrate, had low oral bioavailability in humans, a contradictory anchor; however, the query lacks its specific efflux-prone features and transferability is low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, including a close core analogue with 67% F and multiple heteroaromatic oral drugs with F 30-90%, supports F >=20%; the few low-F analogues are structurally distant and outweighed.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query.",
    "Morgan similarities are all below 0.24, limiting structural transferability.",
    "No human PK, solubility, metabolism, or efflux data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

